/**
 * 구매 적립 포인트 지급 (주문 총액의 1%, 1포인트 미만은 버림)
 * 기존 포인트 적립과 같은 규칙(90일 유효, 사용가능 상태)으로 적립하며, 같은 주문은 한 번만 적립한다.
 *
 * @return 적립된 포인트 (적립하지 않은 경우 0)
 */
@Transactional
public int earnPurchaseReward(User buyer, Long orderId, int totalAmount) {
    int points = totalAmount / 100;
    if (points <= 0) {
        log.info("구매 적립 대상 아님(0포인트): orderId={}, totalAmount={}", orderId, totalAmount);
        return 0;
    }

    String reason = purchaseRewardReason(orderId);
    if (pointRepository.existsByUserAndReason(buyer, reason)) {
        log.info("구매 적립 이미 지급됨: orderId={}, userId={}", orderId, buyer.getId());
        return 0;
    }

    pointRepository.save(new Point(buyer, points, reason));
    log.info("구매 적립 지급: orderId={}, userId={}, points={}", orderId, buyer.getId(), points);
    return points;
}

