/**
 * 구매자에게 구매 적립 포인트를 지급하고, 적립된 경우 혜택 알림을 보냅니다.
 *
 * @param order 배송 완료된 주문
 */
private void rewardBuyer(Order order) {
    User buyer = order.getUser();
    int points = pointCommandService.earnPurchaseReward(buyer, order.getId(), order.getTotalAmount());
    if (points > 0) {
        notificationCommandService.createNotification(
                buyer.getId(),
                NotificationCategory.SHOPPING,
                NotificationType.BENEFIT,
                String.format("구매 적립 %,dP가 지급되었습니다. 주문 ID: %d", points, order.getId())
        );
        log.info("구매 적립 알림 생성: userId={}, orderId={}, points={}", buyer.getId(), order.getId(), points);
    }
}

