                NotificationCategory.SHOPPING,
                NotificationType.BID,
                "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
        );

        log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());

